{
  "mcpServers": {
    "replicate": {
      "command": "npx",
      "args": [
        "-y",
        "replicate-mcp"
      ],
      "env": {
        "REPLICATE_API_TOKEN": "<REPLICATE_API_TOKEN>"
      }
    }
  }
}

{
  "mcpServers": {
    "replicate": {
      "command": "npx",
      "args": ["-y", "replicate-mcp"],
      "env": {
        "REPLICATE_API_TOKEN": "<your-replicate-api-token>"
      }
    }
  }
}

{
  "edit_image": "./edit_image_input_files/cat_sitting_in_chair.jpg",
  "prompts": [
    "Change the fur of the cat to black",
    "Change the fur of the cat to orange",
    "Change the fur of the cat to gray",
    "Change the fur of the cat to yellow",
    "Change the fur of the cat to blue"
  ]
}
